package com.rustyledger;

import java.util.List;

public final class TransactionManager implements Ledger {

    private final State state;

    public TransactionManager() {
        this.state = new State();
    }

    @Override
    public void openAccount(String id, String tier, String currency, String openingBalance) {
        AccountManager.openAccount(state, id, tier, currency, openingBalance);
    }

    @Override
    public String balance(String id) {
        return AccountManager.balance(state, id);
    }

    @Override
    public List<String> auditLog() {
        return state.getAudit();
    }

    @Override
    public String dailyReport(String date) {
        return ReportBuilder.build(state, date);
    }

    @Override
    public String submit(String line) {
        return TransactionProcessor.submit(state, line);
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

public class State {
    Map<String, Object[]> accounts = new HashMap<>();
    Map<String, BigDecimal> used = new HashMap<>();
    Map<String, String[]> txs = new LinkedHashMap<>();
    List<String> audit = new ArrayList<>();
    Map<String, int[]> counts = new HashMap<>();
    Map<String, Map<String, BigDecimal>> fees = new HashMap<>();
    int auditSeq = 0;
    int txSeq = 0;

    public Map<String, Object[]> getAccounts() { return accounts; }
    public Map<String, BigDecimal> getUsed() { return used; }
    public Map<String, String[]> getTxs() { return txs; }
    public List<String> getAudit() { return audit; }
    public Map<String, int[]> getCounts() { return counts; }
    public Map<String, Map<String, BigDecimal>> getFees() { return fees; }
    public int getAuditSeq() { return auditSeq; }
    public void setAuditSeq(int auditSeq) { this.auditSeq = auditSeq; }
    public int getTxSeq() { return txSeq; }
    public void setTxSeq(int txSeq) { this.txSeq = txSeq; }
}

package com.rustyledger;

import java.math.BigDecimal;

public class AccountManager {
    public static void openAccount(State state, String id, String tier, String currency, String openingBalance) {
        if (id == null || id.trim().isEmpty() || id.contains("|")) {
            throw new IllegalArgumentException("INVALID ACCOUNT ID");
        }
        if (!tier.equals("STANDARD") && !tier.equals("PREMIUM") && !tier.equals("STAFF")) {
            throw new IllegalArgumentException("INVALID TIER: " + tier);
        }
        if (!currency.equals("PLN") && !currency.equals("EUR") && !currency.equals("USD")) {
            throw new IllegalArgumentException("INVALID CURRENCY: " + currency);
        }
        if (openingBalance == null || !openingBalance.matches("\\d+(\\.\\d{1,2})?")) {
            throw new IllegalArgumentException("INVALID AMOUNT: " + openingBalance);
        }
        if (state.getAccounts().containsKey(id)) {
            throw new IllegalStateException("ACCOUNT EXISTS: " + id);
        }
        BigDecimal balance = new BigDecimal(openingBalance).setScale(2);
        Object[] acc = new Object[] { tier, currency, balance };
        state.getAccounts().put(id, acc);
    }

    public static String balance(State state, String id) {
        Map<String, Object[]> accounts = state.getAccounts();
        Object[] a = accounts.get(id);
        if (a == null) {
            throw new IllegalArgumentException("UNKNOWN ACCOUNT: " + id);
        }
        return a[2] + " " + a[1];
    }
}

package com.rustyledger;

public class TransactionProcessor {
    public static String submit(State state, String line) {
        if (line == null || line.trim().isEmpty()) {
            return reject(state, null, "???", "BAD_INSTRUCTION", "empty instruction");
        }
        String[] parts = line.split("\\|", -1);
        String verb = parts[0];
        if (!isValidVerb(verb)) {
            return reject(state, verb, null, "BAD_INSTRUCTION", "unknown verb " + verb);
        }
        int want = getFieldCount(verb);
        if (parts.length != want) {
            return reject(state, verb, null, "BAD_INSTRUCTION", verb + " needs " + want + " fields");
        }
        String date = parts[1];
        if (!date.matches("\\d{4}-\\d{2}-\\d{2}")) {
            return reject(state, verb, date, "BAD_DATE", date);
        }
        switch (verb) {
            case "TRANSFER":
                return TransferHandler.doTransfer(state, date, parts[2], parts[3], parseAmount(parts[4]), parts[5]);
            case "WITHDRAW":
                return WithdrawHandler.doWithdraw(state, date, parts[2], parseAmount(parts[3]));
            case "DEPOSIT":
                return DepositHandler.doDeposit(state, date, parts[2], parseAmount(parts[3]));
            case "REVERSE":
                return ReverseHandler.doReverse(state, date, parts[2]);
            default:
                return reject(state, verb, null, "BAD_INSTRUCTION", "unknown verb " + verb);
        }
    }

    private static boolean isValidVerb(String verb) {
        return verb != null && ("TRANSFER".equals(verb) || "WITHDRAW".equals(verb) || "DEPOSIT".equals(verb) || "REVERSE".equals(verb));
    }

    private static int getFieldCount(String verb) {
        if ("TRANSFER".equals(verb)) return 6;
        if ("WITHDRAW".equals(verb)) return 4;
        if ("DEPOSIT".equals(verb)) return 4;
        if ("REVERSE".equals(verb)) return 3;
        return 0;
    }

    private static BigDecimal parseAmount(String text) {
        return new BigDecimal(text).setScale(2);
    }

    private static String reject(State state, String verb, String date, String code, String message) {
        if (date != null) {
            LogManager.incrementCount(state, date, 1);
        }
        LogManager.addAudit(state,
                verb == null ? "???" : verb,
                date == null ? "????-??-????" : date,
                "REJECTED " + code);
        return "REJECTED " + code + ": " + message;
    }

    private static String accept(State state, String verb, String date, String txId, String extra) {
        LogManager.incrementCount(state, date, 0);
        LogManager.addAudit(state, verb, date, "OK " + txId);
        return "OK " + txId + " " + extra;
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class TransferHandler {
    public static String doTransfer(State state, String date, String fromId, String toId, BigDecimal amount, String currency) {
        Map<String, Object[]> accounts = state.getAccounts();
        Object[] from = accounts.get(fromId);
        if (from == null) {
            return TransactionProcessor.reject(state, "TRANSFER", date, "UNKNOWN_ACCOUNT", fromId);
        }
        Object[] to = accounts.get(toId);
        if (to == null) {
            return TransactionProcessor.reject(state, "TRANSFER", date, "UNKNOWN_ACCOUNT", toId);
        }
        if (fromId.equals(toId)) {
            return TransactionProcessor.reject(state, "TRANSFER", date, "SAME_ACCOUNT", "cannot transfer to the same account");
        }
        String fromCur = (String) from[1];
        if (!fromCur.equals(currency)) {
            return TransactionProcessor.reject(state, "TRANSFER", date, "CURRENCY_MISMATCH", fromId + " holds " + fromCur);
        }
        String tier = (String) from[0];
        BigDecimal fee = computeFee(tier, amount);
        String err = LimitManager.checkLimitAndFunds(state, date, fromId, tier, fromCur, (BigDecimal) from[2], amount, fee);
        if (err != null) {
            String[] parts = err.split(":", 2);
            return TransactionProcessor.reject(state, "TRANSFER", date, parts[0].trim(), parts[1].trim());
        }
        BigDecimal credited = amount;
        String toCur = (String) to[1];
        if (!fromCur.equals(toCur)) {
            credited = ConversionEngine.convert(amount, fromCur, toCur, tier);
        }
        from[2] = ((BigDecimal) from[2]).subtract(amount.add(fee));
        to[2] = ((BigDecimal) to[2]).add(credited);
        Map<String, BigDecimal> used = state.getUsed();
        BigDecimal cur = used.getOrDefault(fromId + "|" + date, BigDecimal.ZERO);
        used.put(fromId + "|" + date, cur.add(amount));
        state.setTxSeq(state.getTxSeq() + 1);
        String txId = String.format("TX-%06d", state.getTxSeq());
        Map<String, String[]> txs = state.getTxs();
        txs.put(txId, new String[] {
            "TRANSFER", date, fromId, toId, amount.toString(), fromCur,
            fee.toString(), credited.toString(), "N"
        });
        FeeManager.addFee(state, date, fromCur, fee);
        return TransactionProcessor.accept(state, "TRANSFER", date, txId, "fee=" + fee + " " + fromCur);
    }

    private static BigDecimal computeFee(String tier, BigDecimal amount) {
        if ("STANDARD".equals(tier)) {
            BigDecimal fee = amount.multiply(new BigDecimal("0.005")).setScale(2, RoundingMode.HALF_UP);
            return fee.max(new BigDecimal("0.20"));
        } else if ("PREMIUM".equals(tier)) {
            BigDecimal fee = amount.multiply(new BigDecimal("0.0025")).setScale(2, RoundingMode.HALF_UP);
            return fee.max(new BigDecimal("0.10")).min(new BigDecimal("5.00"));
        } else {
            return BigDecimal.ZERO;
        }
    }
}

package com.rustyledger;

import java.math.BigDecimal;

public class WithdrawHandler {
    public static String doWithdraw(State state, String date, String id, BigDecimal amount) {
        Map<String, Object[]> accounts = state.getAccounts();
        Object[] a = accounts.get(id);
        if (a == null) {
            return TransactionProcessor.reject(state, "WITHDRAW", date, "UNKNOWN_ACCOUNT", id);
        }
        String tier = (String) a[0];
        String currency = (String) a[1];
        BigDecimal fee = "STANDARD".equals(tier) ? new BigDecimal("1.00") : BigDecimal.ZERO;
        String err = LimitManager.checkLimitAndFunds(state, date, id, tier, currency, (BigDecimal) a[2], amount, fee);
        if (err != null) {
            String[] parts = err.split(":", 2);
            return TransactionProcessor.reject(state, "WITHDRAW", date, parts[0].trim(), parts[1].trim());
        }
        a[2] = ((BigDecimal) a[2]).subtract(amount.add(fee));
        Map<String, BigDecimal> used = state.getUsed();
        BigDecimal cur = used.getOrDefault(id + "|" + date, BigDecimal.ZERO);
        used.put(id + "|" + date, cur.add(amount));
        state.setTxSeq(state.getTxSeq() + 1);
        String txId = String.format("TX-%06d", state.getTxSeq());
