public class TransactionProcessor {
    public static String submit(State state, String line) {
        if (line == null || line.trim().isEmpty()) {
            return reject(state, null, "???", "BAD_INSTRUCTION", "empty instruction");
        }
        String[] parts = line.split("\\|", -1);
        String verb = parts[0];
        if (!isValidVerb(verb)) {
            return reject(state, verb, null, "BAD_INSTRUCTION", "unknown verb " + verb);
        }
        int want = getFieldCount(verb);
        if (parts.length != want) {
            return reject(state, verb, null, "BAD_INSTRUCTION", verb + " needs " + want + " fields");
        }
        String date = parts[1];
        if (!date.matches("\\d{4}-\\d{2}-\\d{2}")) {
            return reject(state, verb, date, "BAD_DATE", date);
        }
