package com.rustyledger;

import java.math.BigDecimal;
import java.util.Map;

public class AccountManager {
    public static void openAccount(State state, String id, String tier, String currency, String openingBalance) {
        if (id == null || id.trim().isEmpty() || id.contains("|")) {
            throw new IllegalArgumentException("INVALID ACCOUNT ID");
        }
        if (!tier.equals("STANDARD") && !tier.equals("PREMIUM") && !tier.equals("STAFF")) {
            throw new IllegalArgumentException("INVALID TIER: " + tier);
        }
        if (!currency.equals("PLN") && !currency.equals("EUR") && !currency.equals("USD")) {
            throw new IllegalArgumentException("INVALID CURRENCY: " + currency);
        }
        if (openingBalance == null || !openingBalance.matches("\\d+(\\.\\d{1,2})?")) {
            throw new IllegalArgumentException("INVALID AMOUNT: " + openingBalance);
        }
        if (state.getAccounts().containsKey(id)) {
            throw new IllegalStateException("ACCOUNT EXISTS: " + id);
        }
        BigDecimal balance = new BigDecimal(openingBalance).setScale(2);
        Object[] acc = new Object[] { tier, currency, balance };
        state.getAccounts().put(id, acc);
    }

    public static String balance(State state, String id) {
        Map<String, Object[]> accounts = state.getAccounts();
        Object[] a = accounts.get(id);
        if (a == null) {
            throw new IllegalArgumentException("UNKNOWN ACCOUNT: " + id);
        }
        return a[2] + " " + a[1];
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class ConversionEngine {
    public static BigDecimal rate(String currency) {
        if ("EUR".equals(currency)) {
            return new BigDecimal("4.30");
        } else if ("USD".equals(currency)) {
            return new BigDecimal("4.00");
        }
        return new BigDecimal("1.00");
    }

    public static BigDecimal convert(BigDecimal amount, String from, String to, String tier) {
        BigDecimal inPln = amount.multiply(rate(from)).setScale(4, RoundingMode.HALF_UP);
        BigDecimal result = inPln.divide(rate(to), 4, RoundingMode.HALF_UP);
        if (!"STAFF".equals(tier)) {
            result = result.multiply(new BigDecimal("0.985"));
        }
        return result.setScale(2, RoundingMode.HALF_DOWN);
    }
}

