package com.rustyledger;

import java.math.BigDecimal;
import java.util.Map;
import java.util.TreeMap;

public class FeeManager {
    public static void addFee(State state, String date, String currency, BigDecimal delta) {
        if (delta.signum() == 0) {
            return;
        }
        Map<String, Map<String, BigDecimal>> fees = state.getFees();
        Map<String, BigDecimal> m = fees.get(date);
        if (m == null) {
            m = new TreeMap<>();
            fees.put(date, m);
        }
        BigDecimal old = m.get(currency);
        m.put(currency, old == null ? delta : old.add(delta));
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.util.Map;

public class LimitManager {
    public static BigDecimal usedToday(State state, String id, String date) {
        Map<String, BigDecimal> used = state.getUsed();
        BigDecimal u = used.get(id + "|" + date);
        return u == null ? BigDecimal.ZERO : u;
    }

    public static String checkLimitAndFunds(State state, String date, String id, String tier, String currency, BigDecimal balance, BigDecimal amount, BigDecimal fee) {
        BigDecimal limit;
        BigDecimal overdraft = BigDecimal.ZERO;
        if ("STANDARD".equals(tier)) {
            limit = new BigDecimal("5000.00");
        } else if ("PREMIUM".equals(tier)) {
            limit = new BigDecimal("20000.00");
            overdraft = new BigDecimal("500.00");
        } else {
            limit = new BigDecimal("50000.00");
        }
        BigDecimal used = usedToday(state, id, date);
        if (used.add(amount).compareTo(limit) > 0) {
            return "LIMIT_EXCEEDED: daily limit " + limit + " for " + tier;
        }
        BigDecimal needed = amount.add(fee);
        if (balance.subtract(needed).compareTo(overdraft.negate()) < 0) {
            return "INSUFFICIENT_FUNDS: balance " + balance + " " + currency + ", needed " + needed + " " + currency;
        }
        return null;
    }
}

