package com.rustyledger;

import java.math.BigDecimal;
import java.util.Map;
import java.util.Map.Entry;

public class ReportBuilder {
    public static String build(State state, String date) {
        Map<String, int[]> counts = state.getCounts();
        int[] c = counts.get(date);
        int ok = c == null ? 0 : c[0];
        int rejected = c == null ? 0 : c[1];
        Map<String, Map<String, BigDecimal>> fees = state.getFees();
        Map<String, BigDecimal> f = fees.get(date);
        String feeText = "none";
        if (f != null && !f.isEmpty()) {
            StringBuilder sb = new StringBuilder();
            for (Map.Entry<String, BigDecimal> e : f.entrySet()) {
                if (sb.length() > 0) {
                    sb.append(", ");
                }
                sb.append(e.getValue()).append(" ").append(e.getKey());
            }
            feeText = sb.toString();
        }
        return "REPORT " + date + "\nok: " + ok + "\nrejected: " + rejected + "\nfees: " + feeText;
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.util.Map;

public class ReverseHandler {
    private static String validateReverse(State state, String date, String txId) {
        Map<String, String[]> txs = state.getTxs();
        String[] tx = txs.get(txId);
        if (tx == null) {
            return TransactionProcessor.reject(state, "REVERSE", date, "UNKNOWN_TX", txId);
        }
        if (!"TRANSFER".equals(tx[0])) {
            return TransactionProcessor.reject(state, "REVERSE", date, "NOT_REVERSIBLE", txId + " is a " + tx[0]);
        }
        if ("Y".equals(tx[8])) {
            return TransactionProcessor.reject(state, "REVERSE", date, "ALREADY_REVERSED", txId);
        }
        if (!date.equals(tx[1])) {
            return TransactionProcessor.reject(state, "REVERSE", date, "REVERSAL_WINDOW", txId + " was made on " + tx[1]);
        }
        return null;
    }

    private static String applyReverse(State state, String date, String txId, String[] tx) {
        Map<String, Object[]> accounts = state.getAccounts();
        Object[] from = accounts.get(tx[2]);
        Object[] to = accounts.get(tx[3]);
        BigDecimal fee = new BigDecimal(tx[6]);
        to[2] = ((BigDecimal) to[2]).subtract(new BigDecimal(tx[7]));
        BigDecimal back = new BigDecimal(tx[4]);
        if ("PREMIUM".equals(from[0])) {
            back = back.add(fee);
            if (fee.compareTo(BigDecimal.ZERO) != 0) {
                FeeManager.addFee(state, date, (String) from[1], fee.negate());
            }
        }
        from[2] = ((BigDecimal) from[2]).add(back);
        tx[8] = "Y";
        state.setTxSeq(state.getTxSeq() + 1);
        String newId = String.format("TX-%06d", state.getTxSeq());
        Map<String, String[]> txs = state.getTxs();
        txs.put(newId, new String[] {
            "REVERSE", date, tx[2], tx[3], tx[4], tx[5], "0.00", tx[7], "Y"
        });
        return TransactionProcessor.accept(state, "REVERSE", date, newId, "reversed " + txId);
    }

    public static String doReverse(State state, String date, String txId) {
        String err = validateReverse(state, date, txId);
        if (err != null) {
            return err;
        }
        Map<String, String[]> txs = state.getTxs();
        String[] tx = txs.get(txId);
        return applyReverse(state, date, txId, tx);
    }
}

